                for r in range(lo + 2, hi - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1

    # With just two diagonally separated crosses, extend their facing arms
    # toward one another along the horizontal and vertical projections.
    if len(centers) == 2:
        (r1, c1), (r2, c2) = centers
        if r1 < r2 and c1 < c2:
